import{createFrog,pull,releaseHand,pressRear,releaseRear,advance,cancelControls,obstacleAt,nudge}from'./core.mjs';
const $=id=>document.getElementById(id),canvas=$('pond'),ctx=canvas.getContext('2d'),hands=[...document.querySelectorAll('[data-hand]')],rears=[...document.querySelectorAll('[data-rear]')],buttons=[...hands,...rears],keys={a:0,d:1,j:2,k:3};let s=createFrog(),best=+(localStorage.getItem('swim-off-best-v2')||0),last=performance.now(),camera=0,clock=0,hit=new Set();$('best').textContent=`${Math.floor(best)} m`;
function begin(){s=createFrog();s.status='playing';camera=clock=0;hit.clear();last=performance.now();$('overlay').hidden=true;$('share').hidden=true;sync()}
function finish(){best=Math.max(best,s.z);localStorage.setItem('swim-off-best-v2',best);$('best').textContent=`${Math.floor(best)} m`;$('overlay-label').textContent='CERTIFIED RIVER GOBLIN';$('overlay-title').textContent=`${Math.floor(s.z)} meters. Splash.`;$('overlay-copy').textContent=`${s.strokes} clean hand pulls. ${s.strokes<4?'Alternate the front hands, then charge a rear leg.':'Those charged frog kicks were almost athletic.'}`;$('start').textContent='SWIM AGAIN →';$('share').hidden=false;$('overlay').hidden=false;sync()}
function pause(){if(s.status!=='playing')return;s.status='paused';cancelControls(s);$('overlay-label').textContent='FLOAT BREAK';$('overlay-title').textContent='Just drifting.';$('overlay-copy').textContent='Stored leg charge was safely released.';$('start').textContent='KEEP SWIMMING →';$('share').hidden=true;$('overlay').hidden=false;sync()}
$('start').onclick=()=>s.status==='paused'?(s.status='playing',last=performance.now(),$('overlay').hidden=true):begin();$('restart').onclick=begin;$('pause').onclick=pause;$('help').onclick=()=>{pause();$('help-dialog').showModal()};$('close-help').onclick=$('got-it').onclick=()=>$('help-dialog').close();
function press(i){if(i<2){if(pull(s,i,clock))nudge(s,i?.04:-.04)}else pressRear(s,i-2);sync()}function lift(i){if(i<2)releaseHand(s,i);else releaseRear(s,i-2);sync()}buttons.forEach((b,i)=>{b.onpointerdown=e=>{if(e.button!==0||s.status!=='playing')return;e.preventDefault();b.setPointerCapture(e.pointerId);press(i)};b.onpointerup=b.onlostpointercapture=e=>{if(s.active[i])lift(i)};b.onpointercancel=()=>{if(s.active[i])lift(i)}});const held=new Set();addEventListener('keydown',e=>{if(e.key==='Escape')return pause();const k=e.key.toLowerCase();if(!(k in keys)||e.repeat||held.has(k))return;e.preventDefault();held.add(k);press(keys[k])});addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k in keys&&held.delete(k))lift(keys[k])});addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>document.hidden&&pause());
function sync(){hands.forEach((b,i)=>{b.classList.toggle('active',s.active[i]);b.classList.toggle('next',i===s.nextHand&&!s.leap);b.setAttribute('aria-pressed',String(s.active[i]))});rears.forEach((b,i)=>{b.classList.toggle('active',s.rear[i]);b.style.setProperty('--charge',s.charges[i]);b.setAttribute('aria-pressed',String(s.rear[i]))});$('rhythm-label').textContent=s.leap?'AIRBORNE — KEEP YOUR EYES UP':`NEXT HAND: ${s.nextHand?'RIGHT':'LEFT'} · COMBO x${s.combo}`;$('feedback').textContent=s.message;$('power-left').value=s.charges[0];$('power-right').value=s.charges[1];$('distance').innerHTML=`${Math.floor(s.z)}<span>m</span>`;$('strokes').textContent=`${s.strokes} clean ${s.strokes===1?'pull':'pulls'}`}
function ellipse(x,y,rx,ry,fill,rot=0){ctx.beginPath();ctx.ellipse(x,y,Math.max(.1,rx),Math.max(.1,ry),rot,0,7);ctx.fillStyle=fill;ctx.fill()}function line(points,color,w){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.strokeStyle=color;ctx.lineWidth=w;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke()}
function webbedFoot(x,y,side,fill){ctx.save();ctx.translate(x,y);ctx.scale(side,1);ctx.beginPath();ctx.moveTo(0,-5);ctx.lineTo(19,-13);ctx.lineTo(13,-2);ctx.lineTo(24,3);ctx.lineTo(11,6);ctx.lineTo(16,17);ctx.lineTo(-3,8);ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle='#164c45';ctx.lineWidth=2;ctx.stroke();ctx.restore()}
function frog(x,y,scale,lift){ctx.save();ctx.translate(x,y-lift);ctx.scale(scale,scale);const outline='#164c45',leap=s.leap?Math.sin(Math.min(1,s.leap.elapsed/s.leap.duration)*Math.PI):0;
// Proper frog hind legs: large folded thigh, long lower leg, and a broad webbed foot.
for(let i=0;i<2;i++){const side=i?-1:1,charge=s.charges[i],extension=leap*(s.leap?.side===i?1:.62),hipX=side*23,hipY=18,kneeX=side*(44-charge*17+extension*16),kneeY=34-charge*14-extension*12,ankleX=side*(30-charge*9+extension*43),ankleY=62-charge*23-extension*29,fill='#9fe36b';ellipse(kneeX,kneeY,22,15,outline,side*.55);ellipse(kneeX,kneeY,18,11,fill,side*.55);line([[hipX,hipY],[kneeX,kneeY],[ankleX,ankleY]],outline,15);line([[hipX,hipY],[kneeX,kneeY],[ankleX,ankleY]],fill,10);webbedFoot(ankleX,ankleY,side,fill)}
ellipse(0,8,33,40,'#91d859');ellipse(0,20,22,23,'#d4ed9a');for(let i=0;i<2;i++){const side=i?-1:1,pullBack=s.active[i]?17:0,fill=i?'#ff9aca':'#bda2ff';line([[side*24,-4],[side*(43-pullBack),8+pullBack]],outline,12);line([[side*24,-4],[side*(43-pullBack),8+pullBack]],fill,7);webbedFoot(side*(43-pullBack),8+pullBack,side,fill)}ellipse(0,-17,37,29,'#b7ed70');for(const side of[-1,1]){ellipse(side*23,-37,15,19,'#b7ed70');ellipse(side*23,-41,9,11,'#fffbe7');ellipse(side*23,-44,4,6,'#163d3b');ellipse(side*25,-47,1.7,2,'#fff')}ctx.restore()}
function draw(dt){const w=canvas.clientWidth,h=canvas.clientHeight,d=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*d)||canvas.height!==Math.round(h*d)){canvas.width=Math.round(w*d);canvas.height=Math.round(h*d)}ctx.setTransform(d,0,0,d,0,0);const bg=ctx.createLinearGradient(0,0,0,h);bg.addColorStop(0,'#163453');bg.addColorStop(1,'#19a5a0');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);camera+=(s.z-camera)*(1-Math.exp(-5*dt));for(let i=0;i<18;i++){const z=Math.floor(camera/5)*5+i*5-camera,x=w/2+Math.sin((camera+z)*.05)*w*.08,y=h-z*17;ctx.strokeStyle='#8fffff18';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,y);ctx.quadraticCurveTo(x,y+8,w,y);ctx.stroke()}for(let i=Math.max(0,Math.floor(camera/13)-1);i<Math.floor(camera/13)+7;i++){const o=obstacleAt(i),dy=o.z-camera;if(dy<0||dy>34)continue;const y=h*.76-dy*h*.022,x=w/2+o.x*w*.34,scale=1-dy*.014;if(o.kind==='log'){ctx.fillStyle='#704b36';ctx.fillRect(x-34*scale,y-7,68*scale,14)}else if(o.kind==='lily')ellipse(x,y,28*scale,11*scale,'#75c95f');else{ctx.save();ctx.translate(x,y);ctx.rotate(.4);ctx.fillStyle='#f493cf';ctx.fillRect(-7,-18,14,36);ctx.restore()}}const fx=w/2+s.x*w*.29,fy=h*.76,air=s.leap?Math.sin(Math.min(1,s.leap.elapsed/s.leap.duration)*Math.PI)*h*.21:0;if(s.status==='playing'&&!s.leap)for(let i=Math.max(0,Math.floor(camera/13)-1);i<Math.floor(camera/13)+2;i++){const o=obstacleAt(i);if(hit.has(i)||Math.abs(o.z-s.z)>1.1||Math.abs(o.x-s.x)>.28)continue;hit.add(i);s.speed*=.45;s.stamina=Math.max(0,s.stamina-8);s.combo=0;s.message='BONK. Charge a rear leg and leap over the next one.'}ellipse(fx,fy+36,38*(1-air/h),10*(1-air/h*.6),'#073f6088');frog(fx,fy,.72,air);ctx.fillStyle='#d5ff6f';ctx.font='bold 10px Arial';ctx.textAlign='center';ctx.fillText(`${Math.round(s.speed*10)/10} m/s`,fx,fy-58-air)}
function frame(now){const dt=Math.min(.04,Math.max(0,(now-last)/1000));last=now;clock+=dt;const before=s.status;advance(s,dt);if(before==='playing'&&s.status==='over')finish();sync();draw(dt);requestAnimationFrame(frame)}$('share').onclick=async()=>{const text=`My frog swam ${Math.floor(s.z)}m using hand pulls and highly charged frog legs. Beat that. 🐸`,url=new URL('/frog/',location.href).href;try{if(navigator.share)await navigator.share({title:'SWIM OFF!',text,url});else await navigator.clipboard.writeText(`${text} ${url}`)}catch{}};sync();requestAnimationFrame(frame);
